"""Reproduce the benchmark from the real API; no remote data requests."""
from pathlib import Path
import json,sys
from time import perf_counter
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'backend'))
from fastapi.testclient import TestClient
from app.main import create_app


def main():
    cases=[('Scheduling improvement',{'scenario':'scheduling'}),('Historical Kisumu weather',{'scenario':'scheduling','weather_dataset':'kisumu-2025-01-14'}),('Normal',{'scenario':'normal'}),('Storm',{'scenario':'storm'}),('High demand',{'scenario':'high_demand'}),('High demand, more storage only',{'scenario':'high_demand','battery_capacity_kwh':40}),('High demand, higher output limit',{'scenario':'high_demand','max_discharge_kw':6}),('No solar or starting energy',{'scenario':'normal','pv_capacity_kw':0,'initial_battery_kwh':0,'reserve_kwh':0})]
    rows=[];evidence={}
    with TestClient(create_app()) as client:
        for label,payload in cases:
            start=perf_counter();r=client.post('/api/simulate',json=payload);r.raise_for_status();d=r.json();elapsed=perf_counter()-start
            evidence[label]={'request':payload,'elapsed_seconds':elapsed,'diagnosis':d['diagnosis'],'comparison':d['comparison'],'plans':{p:d[p]['metrics'] for p in ('baseline','heuristic','optimized')}}
            for p in ('baseline','heuristic','optimized'):
                m=d[p]['metrics'];plan=d[p];overnight=min(plan['hourly'][17]['soc_end_kwh'],*(h['soc_end_kwh'] for h in plan['hourly'][18:]));coverage='N/A' if m['critical_coverage_pct'] is None else f"{m['critical_coverage_pct']:.1f}%"
                rows.append(f"| {label} | {p} | {coverage} | {overnight:.3f} | {m['flexible_served_kwh']:.3f} | {m['flexible_deferred_kwh']:.3f} | {m['conversion_loss_kwh']:.3f} | {m['critical_unserved_kwh']:.3f} |")
    measured=evidence['Scheduling improvement']; gain=measured['comparison']; completed=measured['plans']['optimized']['flexible_served_kwh']
    summary=f"The primary synthetic case completes {completed:.3f} kWh of flexible work. Same-work comparison: {gain['same_flexible_work_completed']}. Midnight battery difference: {gain['battery_preserved_at_midnight_kwh']:.3f} kWh; full-day minimum difference: {gain['minimum_battery_improvement_kwh']:.3f} kWh; conversion-loss reduction: {gain['conversion_loss_reduction_kwh']:.3f} kWh. Heuristic matches key metrics: {gain['heuristic_matches_optimizer_metrics']}. Storm/high-demand battery differences include less optional work, so are not same-work improvements. Capacity changes must be assessed against remaining power and timing limits, not stored energy alone. These are modeled comparisons, not installation specifications."
    text='# Computed benchmark\n\nGenerated by `python scripts/benchmark.py` through the implemented FastAPI endpoints. All three methods receive identical inputs within each case. Demand is synthetic; the historical case substitutes NASA POWER satellite-derived irradiance. No field validation is implied. All energy columns are kWh; overnight minimum uses boundaries 18–24.\n\n| Case | Plan | Critical coverage | Overnight min | Flexible served | Deferred | Conversion losses | Critical unmet |\n|---|---|---:|---:|---:|---:|---:|---:|\n'+'\n'.join(rows)+'\n\n'+summary+'\n\nExact requests, metrics, diagnostic flags, and observed local response times: [JSON evidence](docs/evidence/final-benchmark.json).\n'
    (ROOT/'BENCHMARK.md').write_text(text)
    (ROOT/'docs/evidence/final-benchmark.json').write_text(json.dumps(evidence,indent=2,allow_nan=False)+'\n')
    print(text)

if __name__=='__main__': main()
